Method.Implementation:
s ExistSPRowId=""
if (InSPRowId = "") {
	s SPRowId=0
	for{
		s SPRowId=$o(^DHCSP("0","CredNo",PatIDCard,SPRowId)) 
		Q:SPRowId=""
		s SPStDate=$p($g(^DHCSP(SPRowId)),"^",5)
		continue:(SPStDate>(+$h))
		s SPEndDate=$p($g(^DHCSP(SPRowId)),"^",6)
		continue:(SPEndDate'="")&&(SPEndDate<=(+$h))
		s SPTypeDr=$p($g(^DHCSP(SPRowId)),"^",4)
		continue:SPTypeDr'=PatListType
		s ExistSPRowId=SPRowId
		Q
	}
}
Q:ExistSPRowId'="" "身份证号："_PatIDCard_" 患者类型："_$p(^DHCPatType(PatListType),"^",2)_" 已存在有效记录！"
i SttDate'="" s SttDate=..%ZDH(SttDate)
e  s SttDate=..%SysDate()
i EndDate'="" s EndDate=..%ZDH(EndDate)
if (SttDate'="")&&(EndDate'="")&&(SttDate>EndDate) {
	Q "有效开始日期不能大于有效截止日期！"
}
if (InSPRowId = "") {
	s object=##class(User.DHCSpecPat).%New()
} else {
	s object=##class(User.DHCSpecPat).%OpenId(InSPRowId)
}
s object.DHCSPName=PatName
s object.DHCSPCredNo=PatIDCard
s object.DHCSPNote=PatNote
d object.DHCSPTypeDRSetObjectId(PatListType)
d object.DHCSPLocDRSetObjectId(LocID)
s object.DHCSPStDate=SttDate
s object.DHCSPEndDate=EndDate
i UserID="" s UserID=%session.Get("LOGON.USERID")
i (InSPRowId'="") { 
	d object.DHCSPUpdateUserDRSetObjectId(UserID)
	s object.DHCSPUpdateDate =..%SysDate()
	s object.DHCSPUpdateTime=..%SysTime()
} else {
	d object.DHCSPCreateUserDRSetObjectId(UserID)
	s object.DHCSPCreateDate=..%SysDate()
	s object.DHCSPCreateTime=..%SysTime()
}
Set sc=object.%Save()
If $$$ISERR(sc) {
	Do $System.Status.DisplayError()
	Q 100
}
d object.%Close()
Q 0

q:(Code="")||(Desc="") ""
s rtn=""
if (RowID=""){
	&SQL(insert into SQLUser.DHC_PatListType(DHC_PatTypeCode,DHC_PatTypeDesc,DHC_PatTypeExecCode) Values(:Code,:Desc,:ExecuteCode))
	s rtn=SQLCODE
}else{
	&SQL(Update SQLUser.DHC_PatListType set DHC_PatTypeCode=:Code,DHC_PatTypeDesc=:Desc,DHC_PatTypeExecCode=:ExecuteCode where DHC_PatTypeRowID=:RowID)
	s rtn=SQLCODE
}
q rtn

s result = {}
s result.total = 0, result.success = 0, result.skip = 0
s result.errors = []

s rows = $lfs(TSVContent, $c(10))
for i = 2:1:$ll(rows) {
	s line = $lg(rows, i)
	continue:(line = "")
	s result.total = result.total + 1

	s name = $p(line, $c(9), 1)
	s credNo = $p(line, $c(9), 2)
	s typeCode = $p(line, $c(9), 3)
	s note = $p(line, $c(9), 4)
	s stDate = $p(line, $c(9), 5)
	s endDate = $p(line, $c(9), 6)
	s locCode = $p(line, $c(9), 7)

	#; 校验必填字段
	if (name = "") || (credNo = "") || (typeCode = "") {
		s reason = "必填字段缺失"
		d result.errors.%Push({"row":(i),"reason":(reason)})
		s result.skip = result.skip + 1
		continue
	}

	#; 患者类型代码 → RowId（遍历查找，无 Code 索引）
	s typeDr = ""
	s tmpId = 0
	for {
		s tmpId = $o(^DHCPatType(tmpId))
		q:(tmpId = "")||(typeDr '= "")
		s tmpCode = $p($g(^DHCPatType(tmpId)),"^",1)
		if (tmpCode = typeCode) {
			s typeDr = tmpId
		}
	}
	if (typeDr = "") {
		s reason = "患者类型代码无效: "_typeCode
		d result.errors.%Push({"row":(i),"reason":(reason)})
		s result.skip = result.skip + 1
		continue
	}

	#; 科室代码 → RowId（遍历查找，无 Code 索引）
	s locDr = ""
	if (locCode '= "") {
		s tmpId = 0
		for {
			s tmpId = $o(^CTLOC(tmpId))
			q:(tmpId = "")||(locDr '= "")
			s tmpCode = $p($g(^CTLOC(tmpId)),"^",1)
			if (tmpCode = locCode) {
				s locDr = tmpId
			}
		}
	}

	#; 复用 InsertPatList 入库
	s rtn = ..InsertPatList(name,credNo,note,typeDr,stDate,endDate,UserID,"",locDr)
	if (rtn = 0) {
		s result.success = result.success + 1
	} else {
		d result.errors.%Push({"row":(i),"reason":(rtn)})
		s result.skip = result.skip + 1
	}
}
q result.%ToJSON()
